#include<bits/stdc++.h>
using ll = long long;
using namespace std;
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	ll n, k;
	cin >> n >> k;
	vector<ll> v(n);
	for (auto& i : v) cin >> i;
	set<ll> st;
	ll res = 0;
	ll j = 0;
	for (ll i = 0; i < n; ++i) {
		if (st.count(v[i])) {
			while (st.count(v[i])) {
				st.erase(v[j++]);
			}
		}
		st.insert(v[i]);
		while (st.size() > k) {
			st.erase(v[j++]);
		}
		if (i - j + 1 == k) {
			ll l = *st.begin(), r = *st.rbegin();
			if (r - l + 1 == k) {
				res += 1;
			}
		}
	}
	cout << res;
}
