for i in range(k - 1, n):
    if num[a[i]] == 0: cnt += 1
    num[a[i]] += 1
    if cnt == k:#条件1
        mi = getmin(i - k + 1, i)
        if getmax(i - k + 1, i) == mi + k - 1:#条件2
            ans += 1
    if num[i - k + 1] == 1: cnt -= 1
    num[i - k + 1] -= 1
